INSERT INTO private.authored_event_catalog(case_key,content)
SELECT doc->>'case_key',doc FROM authored
ON CONFLICT(case_key) DO UPDATE SET content=excluded.content;

UPDATE public.event_cases e SET
 situation=c.content->>'situation',
 decision_options=c.content->'decision_options',
 effect_plan=c.content->'effect_plan',
 allowed_roles=ARRAY(SELECT jsonb_array_elements_text(c.content->'allowed_roles')),
 comic_scene=c.content->'comic_scene',
 status='ready'
FROM private.authored_event_catalog c
WHERE e.case_key=c.case_key AND e.case_key IN ('budget-risk-2026-external','budget-risk-2026-ofz_fixed','budget-risk-2026-ofz_float','budget-risk-2026-privatization','budget-risk-2026-reserves')
AND NOT EXISTS(SELECT 1 FROM public.event_assignments a WHERE a.case_id=e.id)
AND NOT EXISTS(SELECT 1 FROM public.event_decisions d WHERE d.case_id=e.id)
AND NOT EXISTS(SELECT 1 FROM public.event_case_outcomes o WHERE o.case_id=e.id);
